args.command:
python3 -c "
import google.auth
from google.cloud import bigquery
projects = ['autocresta', 'consulting-report', 'pmm-report', 'se-leadu', 'se-saihai-looker']
creds, _ = google.auth.default(scopes=['https://www.googleapis.com/auth/bigquery'])
target_table = '01C_alloffiices_visiting_office_interview_management'

for p in projects:
    try:
        client = bigquery.Client(project=p, credentials=creds)
        # Search dataset / tables
        datasets = list(client.list_datasets())
        for ds in datasets:
            tables = list(client.list_tables(ds.dataset_id))
            for t in tables:
                if target_table.lower() in t.table_id.lower():
                    print(f'FOUND: project={p}, dataset={ds.dataset_id}, table={t.table_id}')
                    table_ref = client.get_table(f'{p}.{ds.dataset_id}.{t.table_id}')
                    print('Schema:')
                    for field in table_ref.schema:
                        print(f'  {field.name}: {field.field_type}')
    except Exception as e:
        print(f'Error project {p}: {e}')
"
